public class CurrentPlatformTraceDisassembleAction : DockingAction {
	private static readonly string NAME = "Disassemble";
	private static readonly string MENU_GROUP = "Disassembly";
	private static readonly KeyBindingData KEY_BINDING = new KeyBindingData("D");

	private PluginTool tool;

	public CurrentPlatformTraceDisassembleAction(DebuggerDisassemblerPlugin plugin) : base(NAME, plugin.getName())
    {
		this.tool = plugin.getTool();

		setPopupMenuData(new MenuData(new string[] { NAME }, MENU_GROUP));
		setKeyBindingData(KEY_BINDING);
		setHelpLocation(new HelpLocation(plugin.getName(), "disassemble"));
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		Reqs reqs = Reqs.fromContext(tool, context);
		return reqs != null;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		Reqs reqs = Reqs.fromContext(tool, context);
		if (reqs == null) {
			return false;
		}
		return base.isEnabledForContext(context);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		Reqs reqs = Reqs.fromContext(tool, context);
		if (reqs == null) {
			return;
		}
		ListingActionContext lac = (ListingActionContext) context;
		Address address = lac.getAddress();
		AddressSpace space = address.getAddressSpace();
		AddressSetView set;
		ProgramSelection selection = lac.getSelection();
		if (selection != null && !selection.isEmpty()) {
			set = selection;
		}
		else {
			set = reqs.view()
					.getAddressFactory()
					.getAddressSet(space.getMinAddress(), space.getMaxAddress());
		}
		CurrentPlatformTraceDisassembleCommand cmd =
			new CurrentPlatformTraceDisassembleCommand(tool, set, reqs, address);
		cmd.run(tool, reqs.view());
	}
